let lifeTalkBusy=false,lifePressBusy=false,lifeTalkMatch=null,lifeTalkKey='',lifeClubSeason=null,lifeClubKey='',lifeTalkNote='',lifePressNote='',lifeExpanded=new Set();
function lifeText(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
function lifeChoiceLabel(choices,id){return choices.find(choice=>choice.id===id)?.label||id||'';}
function lifeKeepDetails(panel){for(const details of panel.querySelectorAll('[data-life-detail]')){if(details.open)lifeExpanded.add(details.dataset.lifeDetail);else lifeExpanded.delete(details.dataset.lifeDetail);}}
function lifeDelta(delta){return delta>0?'+'+delta:String(delta);}
function lifeReactionSummary(reactions){const positive=reactions.filter(person=>person.delta>0).length,negative=reactions.filter(person=>person.delta<0).length,neutral=reactions.length-positive-negative;return '긍정 '+positive+'명 · 긴장 '+negative+'명'+(neutral?' · 변화 없음 '+neutral+'명':'');}
function lifeReactionMarkup(reactions){return '<ul class="life-reactions">'+reactions.map(person=>'<li><span><strong>'+lifeText(person.name)+'</strong><small>'+lifeText(person.text||person.feeling)+(person.traits?' · 충성 '+person.traits.loyalty+' / 프로 '+person.traits.professionalism+' / 압박 '+person.traits.pressure:'')+'</small></span><b class="'+(person.delta>0?'life-positive':person.delta<0?'life-negative':'life-neutral')+'">'+lifeDelta(person.delta)+'<small>자신감 '+person.before+' → '+person.after+'</small></b></li>').join('')+'</ul>';}
function renderTeamTalk(){
 if(typeof matchPopupActive!=='undefined'&&matchPopupActive!=='talk')return;
 if(view!=='match'||typeof ClubLife==='undefined')return;const panel=$('team-talk-panel');if(!panel)return;
 if(!state||!['prep','half','late'].includes(state.phase)){if(!panel.hidden)panel.hidden=true;lifeTalkKey='';return;}
 const key=[season.year,season.round,season.competition,state.phase,state.minute,state.decisions?.length||0,state.score?.join(':'),lifeTalkBusy].join('|');if(lifeTalkMatch===state&&lifeTalkKey===key)return;
 if(lifeTalkMatch!==state)lifeTalkNote='';lifeTalkMatch=state;lifeTalkKey=key;lifeKeepDetails(panel);const status=ClubLife.talkStatus(season);panel.hidden=false;
 const chosen=status.last?lifeChoiceLabel(ClubLife.talkChoices,status.last.choice):'',reactions=status.reactions||[];
 panel.innerHTML='<section class="life-talk" aria-labelledby="life-talk-heading" aria-busy="'+lifeTalkBusy+'"><header class="life-section-heading"><div><span class="life-kicker">DRESSING ROOM / '+lifeText(status.window||'선수단 대화')+'</span><h2 id="life-talk-heading">선수들에게 한마디.</h2></div><span class="life-minute">'+state.minute+'′</span></header><p class="life-context">'+(status.available?'선발 선수의 성격과 경기 상황에 맞춰 말하세요. 같은 말에도 반응이 다릅니다.':chosen?'감독의 메시지 · '+lifeText(chosen):lifeText(status.reason||'다음 경기 구간에서 대화할 수 있습니다.'))+'</p>'+(status.available?'<div class="life-talk-choices">'+ClubLife.talkChoices.map(choice=>{return '<button type="button" class="life-choice" data-life-talk="'+choice.id+'" '+(lifeTalkBusy?'disabled':'')+' aria-label="'+lifeText(choice.label)+' · '+lifeText(choice.description)+'"><strong>'+lifeText(choice.label)+'</strong><span>'+lifeText(choice.description)+'</span><small>선택 후 실제 반응 공개</small></button>';}).join('')+'</div>':'')+(reactions.length?'<div class="life-reaction-overview" role="status">'+lifeReactionSummary(reactions)+' · 이번 대화 완료</div><details class="life-details" data-life-detail="reactions" '+(lifeExpanded.has('reactions')?'open':'')+'><summary>선수별 실제 반응 '+reactions.length+'명</summary>'+lifeReactionMarkup(reactions)+'</details>':'')+'<p class="life-rules">경기 전 · 하프타임 · 65분에 한 번씩. 자신감 변화는 최대 ±3이며 다음 경기 구간의 경기력에 작게 반영됩니다. 득점을 보장하지 않습니다. 65분 대화를 하려면 경기 설정의 65분 감독 멈춤을 켜세요.</p>'+(lifeTalkNote?'<p class="life-note" role="status" aria-live="polite" tabindex="-1">'+lifeText(lifeTalkNote)+'</p>':'')+'</section>';
 panel.onclick=event=>{const button=event.target.closest('[data-life-talk]');if(button&&!button.disabled)lifeChooseTalk(button.dataset.lifeTalk,button);};
}
function lifeChooseTalk(choice,button){
 if(lifeTalkBusy||typeof ClubLife==='undefined'||!ClubLife.talkChoices.some(item=>item.id===choice)||!ClubLife.talkStatus(season).available)return;
 lifeTalkBusy=true;if(button)button.disabled=true;
 try{action(()=>{const decision=ClubLife.talk(season,choice);lifeTalkNote=lifeChoiceLabel(ClubLife.talkChoices,decision.choice)+' · 대화를 저장했습니다. 다음 구간에 선수의 반응이 반영됩니다.';});}
 finally{lifeTalkBusy=false;lifeTalkKey='';renderTeamTalk();$('team-talk-panel')?.querySelector('.life-note')?.focus({preventScroll:true});}
}
function lifePressMarkup(question){
 if(!question)return '';const phase=question.phase,title=phase==='before'?'경기 전 인터뷰':'경기 후 인터뷰';
 return '<article class="life-press-question" data-life-question="'+phase+'"><div class="life-press-tag">'+title+' · '+lifeText(question.opponent)+'</div><h3>'+lifeText(question.question)+'</h3>'+(question.answered?'<p class="life-saved-answer"><span aria-hidden="true">✓</span> '+lifeText(lifeChoiceLabel(ClubLife.pressChoices,question.choice))+' · 답변 저장됨</p>':'<div class="life-press-choices">'+ClubLife.pressChoices.map(choice=>'<button type="button" class="life-choice" data-life-press="'+phase+'" data-life-answer="'+choice.id+'" '+(lifePressBusy?'disabled':'')+'><strong>'+lifeText(choice.label)+'</strong><span>'+lifeText(choice.description)+'</span></button>').join('')+'</div>')+'</article>';
}
function lifeMediaMarkup(){
 if(typeof MediaRoom==='undefined')return '';
 return '<div class="media-reviews" aria-label="감독과 선수에 대한 언론 평가">'+MediaRoom.read(season).map(item=>'<article class="media-review media-'+lifeText(item.style)+'"><header class="media-masthead"><strong>'+lifeText(item.outlet)+'</strong><span>'+lifeText(item.desk)+'</span></header><span class="media-verdict">'+lifeText(item.verdict)+'</span><h3>'+lifeText(item.headline)+'</h3><p>'+lifeText(item.body)+'</p><small>'+lifeText(item.fact)+'</small></article>').join('')+'</div>';
}
function renderClubLife(){
 if(view!=='club'||typeof ClubLife==='undefined')return;const panel=$('club-life-panel');if(!panel)return;
 const life=season.clubLife,key=[season.year,season.round,season.competition,state?.phase,life?.press?.length||0,life?.news?.length||0,season.finance?.ledger?.length||0,lifePressBusy].join('|');if(lifeClubSeason===season&&lifeClubKey===key)return;
 if(lifeClubSeason!==season)lifePressNote='';lifeClubSeason=season;lifeClubKey=key;lifeKeepDetails(panel);const press=ClubLife.pressStatus(season),news=ClubLife.news(season);
 panel.innerHTML='<section class="life-centre" aria-labelledby="life-club-heading" aria-busy="'+lifePressBusy+'"><header class="life-section-heading"><div><span class="life-kicker">THE TOUCHLINE / SEASON '+String(season.year).padStart(2,'0')+'</span><h2 id="life-club-heading">오늘의 축구 헤드라인</h2><p>감독의 선택, 선수의 활약. 언론은 어떻게 봤을까요?</p></div></header><p class="life-media-label">게임 속 가상 언론 · 실제 경기 기록을 바탕으로 한 평가</p>'+lifeMediaMarkup()+'<section class="life-newspaper" aria-label="구단 기사와 소식"><header class="life-feed-heading"><h3>구단 기사와 소식</h3><span>'+news.length+'건</span></header><div class="life-news-list">'+(news.length?news.map(item=>'<article class="life-news-card"><div class="life-news-meta"><span>'+lifeText(item.tag||'구단 소식')+'</span><span>'+item.year+'시즌</span></div><h3>'+lifeText(item.headline)+'</h3><p>'+lifeText(item.body)+'</p></article>').join(''):'<article class="life-news-empty"><h3>우리 구단의 첫 이야기를 기다립니다.</h3><p>경기 후에는 감독과 선수의 평가가 달라지고 새 기사가 여기에 바로 표시됩니다.</p></article>')+'</div></section><div class="life-press-summary"><span>언론 평판 <strong>'+lifeText(press.reputation)+'</strong></span><p>'+lifeText(press.message)+'</p></div><div class="life-interviews">'+lifePressMarkup(press.before)+lifePressMarkup(press.after)+'</div><p class="life-rules">인터뷰는 경기 전·후 각각 한 번. 언론 평판과 기사에 반영됩니다. 기사와 인터뷰는 가상 구단의 실제 경기 기록으로 만드는 게임 콘텐츠입니다.</p>'+(lifePressNote?'<p class="life-note" role="status" aria-live="polite" tabindex="-1">'+lifeText(lifePressNote)+'</p>':'')+'</section>';
 panel.onclick=event=>{const button=event.target.closest('[data-life-press]');if(button&&!button.disabled)lifeAnswerPress(button.dataset.lifePress,button.dataset.lifeAnswer,button);};
}
function lifeAnswerPress(phase,choice,button){
 if(lifePressBusy||typeof ClubLife==='undefined'||!['before','after'].includes(phase)||!ClubLife.pressChoices.some(item=>item.id===choice))return;const question=ClubLife.pressStatus(season)[phase];if(!question||question.answered)return;
 lifePressBusy=true;if(button)button.disabled=true;
 try{action(()=>{ClubLife.answerPress(season,phase,choice);lifePressNote=(phase==='before'?'경기 전':'경기 후')+' 인터뷰 · '+lifeChoiceLabel(ClubLife.pressChoices,choice)+' 답변을 저장했습니다. 기사가 구단 소식에 추가됩니다.';});}
 finally{lifePressBusy=false;lifeClubKey='';renderClubLife();$('club-life-panel')?.querySelector('.life-note')?.focus({preventScroll:true});}
}
